\Big]\bigg\}
\nonumber\\
&+\left (1+\frac{q^2}{M'^2-M''^2}\right)\widetilde{V}_3^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)+2\left[\widetilde{V}_5^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)-\widetilde{V}_6^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)\right]\,,\\
\widetilde{V}_5^{\rm{ SLF}}=&\frac{4M''}{ M_0''}\bigg\{2(x-\bar{x}) \frac{({ \bf k}_\bot'\cdot { \bf q}_\bot)^2}{{ \bf q}_\bot^2}-(m''_1-m_2)(\bar xm'_1+xm_2)\nonumber\\
