\nonumber\\
&+\frac{2}{\bar xD'_{ V,{\rm LF}} }\frac{{ \bf k}_\bot'\cdot { \bf q}_\bot}{{ \bf q}_\bot^2}\Big[(xm_2-\bar xm'_1)(m''_1m_2+\bar xxM_0''^2-\bar x^2q^2)\nonumber\\
&+{\bf k}'^2_\bot\big(m''_1-\bar{x}m'_1-\bar{x}m_2\big)+\bar x{\bf k'_\bot\cdot q_\bot}\big(2\bar xm'_1-m''_1+(\bar x-x)m_2\big)\Big]
\nonumber\\
&-\frac{1}{x\bar xD''_{ V,{\rm LF}} }\Big[\bar xm'_1+xm_2-\frac{{ \bf k}_\bot'\cdot { \bf q}_\bot}{{ \bf q}_\bot^2}\big( m'_1+(x-\bar{x})m''_1+2xm_2\big)\Big] \Big[(x-\bar x){\bf k}_\bot''^2-\bar x^2m_1''^2+x^2m_2^2\Big]
\nonumber\\
&+\frac{2}{x\bar x^2D'_{ V,{\rm LF}}D''_{ V,{\rm LF}} }\frac{{ \bf k}_\bot'\cdot { \bf q}_\bot}{{ \bf q}_\bot^2} \Big[{\bf  k}_\bot'\cdot {\bf  k}_\bot''+(xm_2-\bar xm'_1)(xm_2-\bar xm''_1)\Big]\Big[(x-\bar{x}){\bf  k}_\bot''^2-\bar x^2m_1''^2+x^2m_2^2\Big]
\bigg\}
\nonumber\\
&+2\widetilde{V}_1^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)+\left(1-\frac{q^2}{M'^2-M''^2}\right)\widetilde{V}_3^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)\,,\\
\widetilde{V}_6^{\rm{ SLF}}=&\frac{4M'}{ M_0'}\bigg\{(\bar x-x)({\bf k}'^2_\bot+x\bar xM_0'^2+m'_1m_2)\nonumber\\
&+\frac{{ \bf k}_\bot'\cdot { \bf q}_\bot}{{ \bf q}_\bot^2}\Big[x(x-\bar x)M_0'^2+\frac{x-\bar x}{\bar{x}}(m_2^2+{\bf k}'^2_\bot)-(m_2-m_1')(m_2+m_1'')\Big]
\nonumber\\
&-\frac{1}{\bar xD'_{ V,{\rm LF}}} \big(m_2^2+{\bf k}'^2_\bot-\bar x^2M_0'^2\big)\Big[(x-\bar x)(xm_2-\bar xm'_1)+\frac{{ \bf k}_\bot'\cdot { \bf q}_\bot}{{ \bf q}_\bot^2}\big(m''_1+(x-\bar{x})m'_1+2xm_2)\big)\Big]\nonumber\\
&+\frac{2}{\bar xD''_{ V,{\rm LF}}}\frac{{ \bf k}_\bot''\cdot { \bf q}_\bot}{{ \bf q}_\bot^2}\Big[(\bar xm''_1-xm_2)(m'_1m_2+x\bar{x}M_0'^2+{ \bf k}_\bot'^2)-{ \bf k}_\bot'\cdot { \bf k}_\bot''(m'_1-m_2)\Big]\nonumber\\
&+\frac{2}{\bar x^2D'_{ V,{\rm LF}}D''_{ V,{\rm LF}}}\frac{{ \bf k}_\bot''\cdot { \bf q}_\bot}{{ \bf q}_\bot^2}(m_2^2+{\bf k}'^2_\bot-\bar x^2M_0'^2)\Big[{\bf k}'^2_\bot+\bar x{\bf k'_\bot\cdot q}_\bot+(xm_2-\bar xm'_1)(xm_2-\bar xm''_1)\Big]
\bigg\}\nonumber\\
&+2\widetilde{V}_1^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)-\left(1-\frac{q^2}{M'^2-M''^2}\right)\widetilde{V}_3^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)\,,
