\nonumber\\
&-{\bf k'_\bot\cdot q_\bot}(\bar xm'_1-xm_2)\left((\bar xm''_1+xm_2)(m'_1+m''_1)+\bar x^2{\bf q}_\bot^2+x\bar x({M'}^{2}-{M''}^{2})\right)\Big]\nonumber\\
&-\frac{1}{D''_{ V,{\rm LF}}}\Big[x\bar x(m'_1+m''_1)({M'}^{2}-{M''}^{2}-q^2){\bf k'_\bot\cdot k''_\bot}\nonumber\\
&-(x-\bar x)(m'_1+m''_1){\bf  k''_\bot\cdot q_\bot} {\bf k}_\bot'^2-\bar x(\bar xm'_1+xm_2){\bf  k''_\bot\cdot q_\bot} ({\bf k}_\bot'+{\bf  k}_\bot'')\cdot{\bf q}_\bot\nonumber\\
&-(\bar xm'_1+xm_2)\big((m'_1+m''_1)(xm_2-\bar xm''_1)-x\bar x({M'}^{2}-{M''}^{2})
\big){\bf  k''_\bot\cdot q_\bot}
\Big]\nonumber\\
&-\frac{2\bar x^2}{ D'_{ V,{\rm LF}}D''_{ V,{\rm LF}}}\Big[{\bf k}_\bot'^2{\bf q}_\bot^2-({\bf k'_\bot\cdot q_\bot})^2\Big]\Big[{m'_1}^{2}-{m''_1}^{2}-x (M'^{2}-M''^{2})+ {\bf( k'_\bot+ k''_\bot)\cdot q_\bot}\Big]\bigg\}\,,\\
\widetilde{A}_{2}^{\rm{ SLF}}=&\frac{2\,q^2}{({M'}^{2}-{M''}^{2})^2}\bigg\{
\frac{{\bf k}_\bot'^2}{x^2\bar x}\Big[2(\bar x-x){\bf k}_\bot'^2+\bar x(2+x^2-5x\bar x){\bf q}_\bot^2+2\bar x^2({m'_1}^{2}+{m''_1}^{2})\nonumber\\
&+2(xm'_1+\bar xm_2)(xm''_1+\bar xm_2)-2(\bar x-x)m_2^2-x^2(x-\bar x) ({M'}^{2}+{M''}^{2})\Big]\nonumber\\
&+\frac{\bf k'_\bot\cdot q_\bot}{x^2}\Big[4(x-\bar x){ \bf k}_\bot'^2-2x{\bf k'_\bot\cdot q_\bot}-x\bar x(\bar x-x)q^2+\bar{x}(3x-4)m_1'^2+x\bar x{m''_1}^{2}\nonumber\\
&+4x^2m_2^2-4xm'_1m_2-2x^2(m'_1-m_2)(m''_1-m_2)+(x-\bar x)\cdot x^2({M'}^{2}+{M''}^{2})\Big]\nonumber\\
&-\frac{\bar x m'_1+xm_2}{x^2\bar x} \Big[\bar{x}(x^2 m_2+\bar{x}^2m_1'+\bar{x}m_1')q^2-2m'_1m''_1(\bar x{m''_1}+xm_2)\nonumber\\
&+x^2(\bar x m''_1+xm_2) ({M'}^{2}+{M''}^{2})\Big]\nonumber\\
&+\frac{1}{x\bar xD'_{ V,{\rm LF}}}\Big[{ \bf k}_\bot'^2(m'_1+m''_1)\big(2{\bf k}_\bot'^2+2m_2^2+2\bar x(m'_1+m_2)(m''_1-m_2)-\bar x x({M'}^{2}+{M''}^{2})\big)\nonumber\\
&+{ \bf q}_\bot^2 { \bf k}_\bot'^2\, \bar x\big((2\bar x-x)m'_1+xm''_1+2(\bar x-x)m_2\big)+{ \bf k}_\bot'\cdot{ \bf q}_\bot{\bf k}_\bot'^2\big((x-\bar x)m''_1-(1+4\bar x)m'_1-2\bar xm_2\big)\nonumber\\
&+2\bar x(m'_1-xm''_1+xm_2)({ \bf k}_\bot'\cdot{ \bf q}_\bot)^2+{ \bf k}_\bot'\cdot{ \bf q}_\bot(xm_2-\bar xm'_1)\big((m'_1+m''_1)(\bar xm''_1+xm_2)\nonumber\\
&-2m'_1m_2-x\bar x({M'}^{2}+{M''}^{2})\big)+{ \bf k}_\bot'\cdot{ \bf q}_\bot\qb^2\bar x^2(xm_2-\bar xm'_1)\Big]\nonumber\\
&+\frac{1}{x\bar xD''_{ V,{\rm LF}}}\Big[\big(({\bf k'_\bot\cdot q_\bot})^2-{\bf k}_\bot'^2 {\bf q}_\bot^2\big)\big(3\bar x^2m'_1+\bar x(x-2\bar x)m_2\big)+2{\bf k}_\bot'^2{ \bf k}_\bot'\cdot{ \bf k}_\bot''(m'_1+m''_1)\nonumber\\
&-2{\bf k'_\bot\cdot q_\bot}{ \bf k}_\bot'\cdot{ \bf k}_\bot''\bar{x}(m'_1-m_2)+\bar x\big((2\bar x+1)m'_1-xm_1''+(x-2)m_2\big){ \bf k}_\bot'\cdot{ \bf k}_\bot''{ \bf q}_\bot^2\nonumber\\
&+{ \bf k}_\bot'\cdot{ \bf k}_\bot''\big(2m_2^2+2\bar x(m'_1-m_2)(m''_1+m_2)-x\bar x({M'}^{2}+{M''}^{2})\big)(m'_1+m''_1)\nonumber\\
&+{ \bf k}_\bot''\cdot{ \bf q}_\bot {\bf k}_\bot'^2\big((x-\bar x)(m'_1+m''_1)-2m'_1\big)+({ \bf k}_\bot''\cdot{ \bf q}_\bot)^2 \bar{x}(\bar xm_1'+xm_2) \nonumber\\
&+{ \bf k}_\bot''\cdot{ \bf q}_\bot (\bar xm_1'+xm_2)\big((m'_1+m''_1)(xm_2-\bar xm''_1)-2m'_1m_2+x\bar x({M'}^{2}+{M''}^{2})\big)\Big]\nonumber\\
&+\frac{2}{x D'_{ V,{\rm LF}}D''_{ V,{\rm LF}}}\Big[\big(({\bf k'_\bot\cdot q_\bot})^2-{\bf k}_\bot'^2{\bf q}_\bot^2\big)
\big({\bar x}^2q^2-2{\bf k'_\bot\cdot k''_\bot}-\bar x({m'_1}^{2}+{m''_1}^{2})-2xm_2^2\nonumber\\
&+x\bar x({M'}^{2}+{M''}^{2})\big)\Big]\bigg\}+\widetilde{A}_{1}^{\rm{ SLF}}(x,{\bf k'_\bot},q^2)\,,\\
\widetilde{A}_{3}^{\rm{ SLF}}=&\frac{4}{x\bar x}\bigg\{\frac{\bf  k_\bot''\cdot q_\bot}{{\bf q}_\bot^2}\Big[(x-\bar{x}){\bf k}_\bot'^2-\bar x^2m_1'^{2}+x^2m_2^2\Big]-{\bf k_\bot'\cdot  k}_\bot''\nonumber\\
&+\frac{1}{D''_{ V,{\rm LF}}}\Big[{\bf k_\bot'\cdot  k_\bot''}\big((x-\bar{x})\bar{x}m'_1+x\bar xm''_1-x\bar xm_2\big)+\bar x^2(\bar xm'_1+xm_2){\bf  k_\bot''\cdot q_\bot}\nonumber\\
&+\Big({\bf k}_\bot'^2+\bar{x}{\bf k'_\bot\cdot q_\bot}-2\frac{({\bf k'_\bot\cdot q_\bot})^2}{{\bf q}_\bot^2}\Big)\left(\bar {x}^2m'_1+x\bar{x}m_2\right)
-\frac{\bf  k_\bot''\cdot q_\bot}{{\bf q}_\bot^2}{\bf k^{\prime2}_\bot}(x-\bar x)(m'_1+m''_1)\nonumber\\
&-\frac{\bf k_\bot''\cdot q_\bot}{{\bf q}_\bot^2}(\bar{x}m'_1+xm_2)(m'_1+m''_1)(xm_2-\bar xm''_1)\Big]\nonumber\\
&+\frac{1}{D'_{ V,{\rm LF}}D''_{ V,{\rm LF}}}\Big[\Big({\bf k}_\bot'^2-\frac{2({\bf k'_\bot\cdot q_\bot})^2}{{\bf q}_\bot^{2}}\Big)\big(\bar {x}{\bf k}_\bot'^2-x\bar{x}^2 q^2\big)+\bar x({\bf k'_\bot\cdot q_\bot}){\bf k}_\bot'^2\nonumber\\
&-{\bf k'_\bot\cdot k''_\bot}(x{\bf k}_\bot'^2-\bar x^2{m'_1}^{2}+x^2m_2^{2})-\frac {\bf k''_\bot\cdot q_\bot }{{\bf q}_\bot^{2}}{\bf k}_\bot'^2(\bar{x}{m'_1}^{2}-\bar{x}{m''_1}^{2}+\bar x^2q^2)\Big]
\bigg\}\,,\label{eq:A3SLF1}\\
\widetilde{A}_{4}^{\rm{ SLF}}=&\frac{4}{x\bar{x}}\bigg\{\bar{x}{\bf k}_\bot'^2-\frac{\bf k'_\bot\cdot q_\bot}{{\bf q}_\bot^{2}}\Big[(\bar x-x)({\bf k}_\bot'^2-2\bar{x}{\bf k'_\bot\cdot q_\bot})+\bar x^2{m''_1}^{2}-x^2m_2^2-\bar x^3q^2\Big]\nonumber\\
&+\frac{1}{D'_{ V,{\rm LF}}}\Big[2\frac{({\bf k'_\bot\cdot q_\bot})^2}{{\bf q}_\bot^{2}} \left((x\bar{x}-\bar x^2)m'_1+x\bar{x}m''_1+x\bar{x}m_2\right)-x\bar x(m'_1+m''_1){\bf k}_\bot'^2\nonumber\\
&-\bar{x}^2(xm_2-\bar xm'_1){\bf k'_\bot\cdot q_\bot}+\frac{\bf k'_\bot\cdot q_\bot}{{\bf q}_\bot^{2}}{\bf k}_\bot'^2(\bar{x}-x)(m'_1+m''_1)\nonumber\\
&-\frac{\bf k'_\bot\cdot q_\bot}{{\bf q}_\bot^{2}}(xm_2-\bar xm'_1)(m'_1+m''_1)(xm_2+\bar xm''_1)\Big]\nonumber\\
&+\frac{1}{ D'_{ V,{\rm LF}}D''_{ V,{\rm LF}}}\Big[2\bar x\frac{({\bf k'_\bot\cdot q_\bot})^2}{{\bf q}_\bot^2}{\bf k'_\bot\cdot k''_\bot}+{\bf k'_\bot\cdot k''_\bot}\big((x-\bar x){\bf k}_\bot'^2-\bar x^2{m'_1}^{2}+x^2m_2^2\big)\nonumber\\
&+\Big(\bar{x}{\bf k}_\bot'^2+\frac{\bf k'_\bot\cdot q_\bot}{{\bf q}_\bot^2}{\bf k}_\bot'^2-2\bar x\frac{({\bf k'_\bot\cdot q_\bot})^2}{{\bf q}_\bot^2}\Big)\big(
{\bar{x}m'_1}^{2}-\bar{x}{m''_1}^{2}+\bar{x}q^2\big)
\Big]
\bigg\}\,.
\end{align}
\section{Theoretical results in the  CLF QM}
\subsection{General formalism}
\begin{figure}[t]
\caption{The Feynman diagram for the matrix element $\cal B$.}
\begin{center}
\includegraphics[scale=0.3]{ff.pdf}
\end{center}
\label{fig:fayn}
\end{figure}

The theoretical framework of CLF QM has been developed by Jaus with the help of a manifestly covariant BS approach as a guide to the calculation~\cite{Jaus:1999zv,Jaus:2002sv}. One can refer to Refs.~\cite{Jaus:1999zv,Jaus:2002sv,Cheng:2003sm} for the detail. In the CLF QM, the matrix element is obtained by calculating the Feynman diagram shown in Fig.~\ref{fig:fayn}. Using the Feynman rules given in Refs.~\cite{Jaus:1999zv,Cheng:2003sm}, the matrix element of $V'\to V''$ transition can be written as a manifest covariant form,
\begin{eqnarray}\label{eq:Bclf1}
{\cal B}=N_c \int \frac{{\rm d}^4 k_1'}{(2\pi)^4} \frac{H_{V'}H_{V''}}{N_1'\,N_1''\,N_2}iS_{\cal B}\,,
\end{eqnarray}
where ${\rm d}^4 k_1'=\frac{1}{2} {\rm d} k_1'^- {\rm d} k_1'^+ {\rm d}^2 \mathbf{k}_{\bot}'$, the denominators $N_{1}^{(\prime,\prime\prime)}=k_{1}^{(\prime,\prime\prime)2}-m_1^{(\prime,\prime\prime)2}+i \epsilon$ and $N_{2}=k_{2}^{2}-m_2^{2}+i \epsilon$  come from the fermion propagators, and $H_{V', V''}$ are  vertex functions. The trace term  $S_{\cal B}$  associated with the fermion loop is written as
\begin{eqnarray}
S_{\cal B}={\rm Tr}\left[\Gamma\, (\not\!k'_1+m'_1)\,(i\Gamma_{V'})\,(-\!\not\!k_2+m_2)\,(i \gamma^0{\Gamma}_{V''}^{\dag} \gamma^0) (\not\!k_1''+m_1'')\right]\,,
\end{eqnarray}
where $\Gamma_{V^{(\prime,\prime\prime)}}$ is the vertex operator written as~\cite{Cheng:2003sm,Choi:2013mda}
\begin{eqnarray}
i\Gamma_V=i\left[\gamma^\mu-\frac{ (k_1-k_2)^\mu}{D_{ V,{\rm con}}}\right]\,,\quad D_{V,{\rm con}}=M+m_1+m_2\,.
\end{eqnarray}

Integrating out the minus components of the loop momentum, one goes from the covariant calculation to the LF one. By closing the contour in the upper complex $k_1'^-$ plane and assuming that $H_{V', V''}$ are analytic within the contour, the integration picks up a residue at $k_2^2=\hat{k}_2^2=m_2^2$ corresponding to put the spectator antiquark on its mass-shell. Consequently, one has the following replacements~\cite{Jaus:1999zv,Cheng:2003sm}
\begin{eqnarray}
N_1 \to \hat{N}_1=x \left( M^2-M_0^2\right)
\end{eqnarray}
an
\begin{eqnarray}\label{eq:type1}
\chi_V = H_V/N\to h_V/\hat{N}\,,\qquad  D_{V,{\rm  con}} \to D_{V,{\rm  LF}}\,,\qquad \text{(type-I)}
\end{eqnarray}
where the LF form of vertex function, $h_V$,  is given by
\begin{eqnarray}
h_V/\hat{N}=\frac{1}{\sqrt{2N_c}}\sqrt{\frac{\bar{x}}{x}}\frac{\psi}{\hat{M}_0}\,.
\label{eq:vPV}
\end{eqnarray}
The Eq.~\eqref{eq:type1} shows the correspondence between manifest covariant  and LF approaches.  In Eq.~\eqref{eq:type1},  the correspondence between $\chi$ and $\psi$  can be clearly derived by matching the CLF expressions to the SLF ones via some zero-mode independent  quantities, such as  $f_P$ and  $f_{+}^{P\to P}(q^2)$~\cite{Jaus:1999zv,Cheng:2003sm}, however, the validity of the correspondence for the $D$ factor appearing in the vertex operator, $D_{V{\rm  con}} \to D_{V,{\rm  LF}}$, has not yet been clarified explicitly~\cite{Choi:2013mda}. Instead of the traditional type-I correspondence, a much more generalized correspondence,
\begin{eqnarray}\label{eq:type2}
\chi_M = H_M/N\to h_M/\hat{N}\,,\qquad  M\to  M_0\,,\qquad \text{(type-II)}
\end{eqnarray}
is suggested by Choi {\it et al.} for  the purpose of  self-consistent results for $f_{A,V}$~\cite{Choi:2013mda,Chang:2018zjq}. Our following theoretical results are given within traditional type-I scheme unless otherwise specified. The ones within type-II scheme can be easily obtained by making an additional replacement $M\to  M_0$.

After integrating out $k_1'^-$, the matrix element, Eq.~\eqref{eq:Bclf1}, can be reduced to the LF form
\begin{eqnarray}
\label{eq:Bclf2}
\hat{{\cal B}}=N_c \int \frac{{\rm d} x {\rm d}^2 \mathbf{k}_{\bot}'}{2(2\pi)^3}\frac{h_{M'}h_{M''}}{\bar{x} \hat{N}_1'\,\hat{N}_1''\,}\hat{S}_{\cal B}\,.
\end{eqnarray}
It should be noted that ${\cal B}$ receives additional spurious contributions proportional to the light-like vector $\omega^\mu=(0,2,\mathbf{0}_\bot)$, and these undesired spurious contributions are expected to be cancelled out by the zero-mode contributions~\cite{Jaus:1999zv,Cheng:2003sm}. The inclusion of the zero-mode contributions in practice amounts to some proper replacements in  $\hat{S}_{\cal B}$ under integration~\cite{Jaus:1999zv}. In this work, we need
\begin{align}
 \label{eq:repFF1}
\hat{k}_1'^{\mu} \to& P^\mu A_1^{(1)}+q^\mu A_2^{(1)} \,,\\
\hat{k}_1'^{\mu}\hat{k}_1'^{\nu} \to &g^{\mu\nu}A_1^{(2)}+P^\mu P^\nu A_2^{(2)}+(P^\mu q^\nu+q^\mu P^\nu)A_3^{(2)}+q^\mu q^\nu A_4^{(2)}\nonumber\\
&+\frac{P^\mu\omega^\nu+\omega^\mu P^\nu}{\omega\cdot P}B_1^{(2)}\,,\\
\hat k_1'^{\mu}\hat k_1'^{\nu}\hat k_1'^{\alpha}\to&\left(g^{\mu \nu}P^\alpha+g^{\mu \alpha}P^\nu+g^{\nu\alpha}P^\mu\right)A_1^{(3)}+\left(g^{\mu \nu}q^\alpha+g^{\mu \alpha}q^\nu+g^{\nu\alpha}q^\mu\right)A_2^{(3)}\nonumber\\
&+P^\mu P^\nu P^\alpha A_3^{(3)}+\left(P^\mu P^\nu q^\alpha+P^\mu q^\nu P^\alpha+q^\mu P^\nu P^\alpha\right)A_4^{(3)}\nonumber\\
&+\left(q^\mu q^\nu P^\alpha+q^\mu P^\nu q^\alpha+P^\mu q^\nu q^\alpha\right)A_5^{(3)}+q_\mu q_\nu q_\alpha A_6^{(3)}\nonumber\\
&+\frac{1}{\omega \cdot P}\left(P^\mu P^\nu\omega^\alpha+P^\mu \omega^\nu P^\alpha+\omega^\mu P^\nu P^\alpha\right)B_1^{(3)}\nonumber\\
&+\frac{1}{\omega\cdot P}\left[\left(P^\mu q^\nu+q^\mu P^\nu\right)\omega^\alpha+\left(P^\mu q^\alpha+q^\mu P^\alpha\right)\omega^\nu+\left(P^\alpha q^\nu+q^\alpha P^\nu\right)\omega^\mu\right]B_2^{(3)}\,,\\
k_1'^{\mu}\hat{N}_2\to& q^\mu\left(A_2^{(1)}Z_2+\frac{q\cdot P}{q^2}A_1^{(2)} \right) \,,\\
\hat{k}_1'^{\mu}\hat{k}_1'^{\nu}\hat{N}_2\to &g^{\mu\nu}A_1^{(2)}Z_2+q^\mu q^\nu\left( A_4^{(2)}Z_2+2\frac{q\cdot P}{q^2}A_2^{(1)}A_1^{(2)}\right)+\frac{P^\mu\omega^\nu+\omega^\mu P^\nu}{\omega\cdot P}B_3^{(3)}\,,\\
\hat k_1'^{\mu}\hat k_1'^{\nu}\hat k_1'^{\alpha}\hat N_2\to &\left(g^{\mu \nu}q^\alpha+g^{\mu \alpha}q^\nu+g^{\nu \alpha}q^\mu\right)\left(A_2^{(3)}Z_2+\frac{q\cdot P}{q^2}A_1^{(4)}\right)+q^\mu q^\nu q^\alpha \left(A_6^{(3)}Z_2+3\frac{q\cdot P}{q^2}A_4^{(4)}\right)\nonumber\\
&+\frac{1}{\omega\cdot P}\left[\left(P^\mu q^\nu+q^\mu P^\nu\right)\omega^\alpha+\left(P^\mu q^\alpha+q^\mu P^\alpha\right)\omega^\nu+\left(P^\alpha q^\nu+q^\alpha P^\nu\right)\omega^\mu\right]B_5^{(4)}
 \label{eq:repFF}
\end{align}
where $A$ and $ B$ functions are given by
\begin{align}
A_1^{(1)}&=  \frac{x}{2}\,,\qquad
A_2^{(1)}=\frac{x}{2} -\frac{{ \bf k}_\bot' \cdot { \bf q}_\bot }{q^2}\,;\\
A_1^{(2)}&=-{ \bf k}_\bot'^2 -\frac{({ \bf k}_\bot' \cdot { \bf q}_\bot)^2}{q^2}\,,\qquad
A_2^{(2)}=(A_1^{(1)})^2\,,\qquad
A_3^{(2)}=A_1^{(1)}A_2^{(1)}\,,\qquad
A_4^{(2)}=(A_2^{(1)})^2\,;\\
A_1^{(3)}&=A_1^{(1)}A_1^{(2)}\,,\qquad
A_2^{(3)}=A_2^{(1)}A_1^{(2)}\,,\qquad
A_3^{(3)}=A_1^{(1)}A_2^{(2)}\,,\qquad
A_4^{(3)}=A_2^{(1)}A_2^{(2)}\,,\nonumber\\
A_5^{(3)}&=A_1^{(1)}A_4^{(2)}\,,\qquad
A_6^{(3)}=A_2^{(1)}A_4^{(2)}-\frac{2}{q^2}A_2^{(1)}A_1^{(2)}\,;\\
A_3^{(4)}&=A_1^{(1}A_2^{(3)}\,;\\
B_1^{(2)}&=\frac{x}{2}Z_2-A_1^{(2)}\,;\\
 B_2^{(3)}&=\frac{x}{2}Z_2A_2^{(1)}+A_1^{(1)}A_1^{(2)} \frac{P\cdot q}{q^2}-A_2^{(1)}A_1^{(2)},
~~B_3^{(3)}=B_1^{(2)}Z_2+\left(P^2-\frac{(q\cdot P)^2}{q^2}\right)A_1^{(1)}A_1^{(2)};\\
 B_1^{(4)}&=\frac{x}{2}Z_2A_1^{(2)}-A_1^{(4)}\,,\qquad
B_5^{(4)}=B_2^{(3)}Z_2+\frac{q\cdot P}{q^2}B_1^{(4)}+\left[P^2-\frac{\left(q\cdot P\right)^2}{q^2}\right]A_3^{(4)} \,;\\
Z_2&=\hat{N}_1'+m_1'^2-m_2^2+(\bar{x}-x)M'^2+(q^2+q\cdot P)\frac{{ \bf k}_\bot' \cdot { \bf q}_\bot}{q^2}\,.
\end{align}
In these formulas, the $\omega$-dependent terms associated with the  $C$ functions are not shown because they can be eliminated exactly by the inclusion of the zero-mode contributions~\cite{Jaus:1999zv}. It should be noted that there are still some residual $\omega$-dependences associated with the  $B$ functions, which can be clearly seen from Eq.~(\ref{eq:repFF1}-\ref{eq:repFF}). As illustrated in Ref.~\cite{Jaus:1999zv}, the $B$ functions  play a special role since, on the one hand, it is combined with $\omega^\mu$, on the other hand, there is no zero-mode contribution associated with $B$ due to $x\hat{N}_2=0$.  Therefore, a different mechanism is required to neutralize the residual $\omega$-dependence .

\subsection{Theoretical results}
Using the formalism introduced in the last subsection, we can obtain  ${\cal B}_{\rm  CLF}^\mu$ for the $V'\to V''$ transition.  Then, matching ${\cal B}_{\rm  CLF}^\mu(\Gamma= \gamma^\mu)$ and ${\cal B}_{\rm  CLF}^\mu(\Gamma= \gamma^\mu \gamma_5)$  to the definitions of  form factors, Eq.~\eqref{eq:defFV} and Eq.~\eqref{eq:defFA}, respectively, we can extract the CLF results for the form factors of $V'\to V''$ transition directly. They can be written as
\begin{eqnarray}\label{eq:FCLF}
[\mathcal F(q^2)]_{\rm CLF}=N_c\int\frac{{\rm d} x{\rm d}^2{\bf k'_\bot}}{2(2\pi)^3}\frac{\chi_V'\chi_V''}{\bar x}{\cal \widetilde{\cal F}}^{\rm CLF}(x,{\bf k'_\bot},q^2)
\end{eqnarray}
where, the integrands are
\begin{align}
\label{eq:V1CLF}
\widetilde{V}_1^{\rm{CLF}}=&2\bigg\{x(m'_1+m''_1)m_2+\frac{1}{\bar x}({ \bf k}_\bot'^2+x^2m_2^2)-{\bf k'_\bot\cdot q_\bot}+\bar xm'_1m''_1+8A_1^{(3)}\nonumber\\
&-\frac{2}{D'_{ V,{\rm con}}}\left[m'_1\left(-A_1^{(2)}+4A_1^{(3)}\right)+m'_1 A_1^{(2)}+4m_2A^{(3)}_1\right]\nonumber\\
&-\frac{2}{D''_{ V,{\rm con}}}\left[m'_1 A_1^{(2)}+m''_1\left(-A_1^{(2)}+4A_1^{(3)}\right)+4m_2 A^{(3)}_1\right]\nonumber\\
&-\frac{4}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}A_1^{(2)}\Big[\frac{1}{\bar x}({\bf k'_\bot}^{2}+x^2m_2^2)-{\bf k'_\bot\cdot q_\bot}+\bar xm'_1m''_1-x(m'_1+m''_1)m_2\Big]
\bigg\}\,, \\
\widetilde{V}_2^{\rm CLF}=&2{M'}^2-2(m_1'-m_2)^2+(m_1'-m_1'')^2-q^2-\hat N'_1+\hat N''_1-2Z_2-16A_2^{(3)}\nonumber\\
&+2\left[2(m_2-m'_1)(m_2-m''_1)-{M'}^{2}-{M''}^{2}+q^2+2Z_2\right]A_2^{(1)}+4\left(2+\frac{{M'}^{2}-{M''}^{2}}{q^2}\right)A_1^{(2)}\nonumber\\
&+\frac{4}{D'_{ V,{\rm con}}}\left[m'_1\left(4A_2^{(3)}-3A_1^{(2)}\right)+m''_1 A_1^{(2)}+2m_2\left(2A_2^{(3)}-A_1^{(2)}\right)\right]\nonumber\\
&+\frac{4}{D''_{ V,{\rm con}}}\left[-m'_1 A_1^{(2)}+m''_1\left(4A_2^{(3)}-A_1^{(2)}\right)+2m_2\left( 2A_2^{(3)}-A_1^{(2)}\right)\right]\nonumber\\
&+\frac{4}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}\bigg\{\Big[-2{M'}^{2}-(m'_1-m''_1)^2+2(m'_1-m_2)^2+q^2+\hat N'_1-\hat N''_1+2Z_2\nonumber\\
&-\frac{4({M'}^{2}-{M''}^{2})}{3q^2}A_1^{(2)}\Big]A_1^{(2)}+2\left[{M'}^{2}+{M''}^{2}-2(m'_1+m_2)(m''_1+m_2)-q^2-2Z_2\right]A_2^{(3)}\bigg\}\,,\\
\widetilde{V}_3^{\rm CLF}=&4\left({M'}^{2}-{M''}^{2}\right)\bigg\{4\left(A_3^{(2)}-A_2^{(2)}+A_3^{(3)}-A_5^{(3)}\right)\nonumber\\
&+\frac{1}{D'_{ V,{\rm con}}}\Big[(x-\bar x)m'_1\left(A_1^{(1)}-A_2^{(1)}-A_2^{(2)}+A_4^{(2)}\right)
+m''_1\left(A_2^{(2)}-2A_3^{(2)}+A_4^{(2)}\right)\nonumber\\
&+xm_2\left(A_1^{(1)}-A_2^{(1)}-2A_2^{(2)}+2A_4^{(2)}\right)\Big]\nonumber\\
&+\frac{1}{D''_{ V,{\rm con}}}\Big[m'_1\left(\bar x-2A_2^{(1)}+A_2^{(2)}+2A_3^{(2)}+A_4^{(2)}\right)+(x-\bar x)m''_1\left(A_1^{(1)}-A_2^{(1)}-A_2^{(2)}+A_4^{(2)}\right)\nonumber\\
&+2m_2\left(A_1^{(1)}+A_2^{(2)}-3A_3^{(2)}-2A_3^{(3)}+2A_5^{(3)}\right)\Big]\nonumber\\
&+\frac{2}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}\left(A_1^{(1)}-A_2^{(1)}-A_2^{(2)}+A_4^{(2)}\right)\Big[\frac{1}{\bar x}({\bf k'_\bot}^{2}+x^2m_2^2)-{\bf k'_\bot\cdot q_\bot}\nonumber\\
&+\bar xm'_1m''_1-x(m'_1+m''_1)m_2\Big]
\bigg\}\,,\\
\widetilde{V}_4^{\rm CLF}=&-4q^2\bigg\{2\left(-A_1^{(1)}+A_2^{(1)}+A_2^{(2)}+2A_3^{(2)}-3A_4^{(2)}-2A_4^{(3)}+2A_6^{(3)}\right)\nonumber\\
&+\frac{1}{D'_{ V,{\rm con}}}\Big[m'_1\left(3A_1^{(1)}-3A_2^{(1)}-3A_2^{(2)}-4A_3^{(2)}+7A_4^{(2)}+4A_4^{(3)}-4A_6^{(3)}\right)\nonumber\\
&+m''_1\left(A_2^{(2)}-2A_3^{(2)}+A_4^{(2)}\right)-2m_2\left(A_2^{(2)}+A_3^{(2)}-2A_4^{(2)}-2A_4^{(3)}+2A_6^{(3)}\right)\Big]\nonumber\\
&+\frac{1}{D''_{ V,{\rm con}}}\Big[m'_1\left(-\bar x+2A_2^{(1)}-A_2^{(2)}-2A_3^{(2)}-A_4^{(2)}\right)+m''_1\Big(A_1^{(1)}-A_2^{(1)}-A_2^{(2)}-4A_3^{(2)}\nonumber\\
&+5A_4^{(2)}+4A_4^{(3)}-4A_6^{(3)}\Big)+2m_2\left(A_1^{(1)}-2A_2^{(1)}-A_2^{(2)}-A_3^{(2)}+4A_4^{(2)}+2A_4^{(3)}-2A_6^{(3)}\right)\Big]\nonumber\\
&+\frac{1}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}\Big[2\left({M'}^{2}+{M''}^{2}-2(m'_1+m_2)(m''_1+m_2)-q^2\right)\Big(A_4^{(2)}-A_3^{(2)}+A_4^{(3)}-A_6^{(3)}\Big)\nonumber\\
&+\Big(2{M'}^{2}+(m'_1-m''_1)^2-2(m'_1+m_2)^2-q^2-\hat N'_1+\hat N''_1\Big)\Big(A_1^{(1)}-A_2^{(1)}-A_2^{(2)}+A_4^{(2)}\Big)\nonumber\\
&+\frac{2({M'}^{2}-{M''}^{2})}{q^2}\Big(A_1^{(2)}-6A_2^{(1)}A_1^{(2)}+6A_2^{(1)}A_2^{(3)}-\frac{2}{q^2}(A_1^{(2)})^2\Big)\nonumber\\
&+Z_2\left(2A_2^{(1)}-6A_4^{(2)}+4A_6^{(3)}\right)\Big]\bigg\}
+\widetilde{V}_3^{\rm CLF}(x,{\bf k'_\bot},q^2)\,,\\
\widetilde{V}_5^{\rm CLF}=&2\bigg\{{M'}^{2}-(m'_1-m_2)^2-\hat N'_1-Z_2-8\left(A_1^{(3)}-A_2^{(3)}\right)\nonumber\\
&+\left[{M'}^{2}-{M''}^{2}+2(m''_1-m'_1)(m''_1-m_2)-q^2
+2\hat N''_1\right]\left(A_1^{(1)}-A_2^{(1)}\right)\nonumber\\
&+\frac{2}{D'_{ V,{\rm con}}}\Big[m'_1\Big(\big({M''}^{2}-{m''_1}^{2}-m_2^{2}-\hat{N}_1''\big)\big(A_1^{(1)}-A_2^{(1)}\big)+4\big(A_1^{(3)}-A_2^{(3)}\big)+Z_2A_2^{(1)}\nonumber\\
&+\frac{{M'}^{2}-{M''}^{2}}{q^2}A_1^{(2)}\Big)-m''_1\Big(\big({M'}^{2}-{m'_1}^{2}-m_2^{2}-\hat N'_1\big)\big(A_1^{(1)}-A_2^{(1)}\big)+Z_2A_2^{(1)}+\frac{{M'}^{2}-{M''}^{2}}{q^2}A_1^{(2)}\Big)\nonumber\\
&-m_2\left(4A_2^{(3)}-4A_1^{(3)}\right)-m_2\left((m'_1-m''_1)^2-q^2+\hat N'_1+\hat N''_1\right)\left(A_1^{(1)}-A_2^{(1)}\right)\Big]\nonumber\\
&-\frac{2}{D''_{ V,{\rm con}}}\Big[2m'_1A_1^{(2)} -4m''_1\left(A_1^{(3)}-A_2^{(3)}\right)
-2m_2\left(A_1^{(2)}+2A_1^{(3)}-2A_2^{(3)}\right)\Big]\nonumber\\
&+\frac{4}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}\Big[\Big({M'}^{2}+{M''}^{2}-2(m'_1+m_2)(m''_1+m_2)-q^2\Big)\Big(A_1^{(3)}-A_2^{(3)}\Big)\nonumber\\
&+2Z_2A_2^{(3)}+\frac{2({M'}^{2}-{M''}^{2})}{3q^2}\Big(A_1^{(2)}\Big)^2\Big]
\bigg\}\,,\\
\widetilde{V}_6^{\rm CLF}=&2\bigg\{{M'}^{2}-(m'_1-m''_1)^2-(m'_1-m_2)^2+q^2-2\hat N'_1-\hat N''_1-Z_2+8\left(A_1^{(2)}-A_1^{(3)}-A_2^{(3)}\right)\nonumber\\
&+\Big[{M''}^{2}-{M'}^{2}+2(m'_1-m''_1)(m'_1-m_2)-q^2+2\hat N'_1\Big]\Big(A_1^{(1)}+A_2^{(1)}\Big)\nonumber\\
&+\frac{2}{D'_{ V,{\rm con}}}\Big[4m'_1\left(A_1^{(3)}+A_2^{(3)}-A_1^{(2)}\right)-2m''_1 A_1^{(2)}-2m_2\left(A_1^{(2)}-2A_1^{(3)}-2A_2^{(3)}\right)\Big]\nonumber\\
&+\frac{2}{D''_{ V,{\rm con}}}\Big[m'_1\Big({M''}^{2}-{m''_1}^{2}-m_2^{2}-\hat N''_1-Z_2+Z_2A_2^{(1)}+\frac{M^{'2}-M^{''2}}{q^2}A_1^{(2)}\Big)\nonumber\\
&+m_1'({m''_1}^{2}+m_2^{2}-{M''}^{2}+\hat N''_1)\left(A_1^{(1)}+A_2^{(1)}\right)+m''_1\left({M'}^{2}-{m'_1}^{2}-m_2^{2}-\hat N'_1\right)\left(A_1^{(1)}+A_2^{(1)}\right)\nonumber\\
&+m''_1\left({m'_1}^{2}+m_2^{2}-{M'}^{2}+\hat N'_1+Z_2-4A_1^{(2)}+4A_1^{(3)}+4A_2^{(3)}-Z_2A_2^{(1)}-\frac{({M'}^{2}-{M''}^{2})}{q^2}A_1^{(2)}\right)\nonumber\\
&+m_2\big((m'_1-m''_1)^2-q^2+\hat N'_1+\hat N''_1\big)\big(1-A_1^{(1)}-A_2^{(1)}\big)+4m_2\big(-A_1^{(2)}+A_1^{(3)}+A_2^{(3)}\big)\Big]\nonumber\\
&+\frac{4}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}\Big[\big(-{M'}^{2}-{M''}^{2}+q^2+2(m'_1+m_2)(m''_1+m_2)\big)\big(A_1^{(2)}-A_1^{(3)}-A_2^{(3)}\big)\nonumber\\
&+2Z_2(A_1^{(2)}-A_2^{(3)})-\frac{2({M'}^{2}-{M''}^{2})}{3q^2}\big(A_1^{(2)}\big)^2\Big]\bigg\}\,,
\end{align}
\begin{align}
\widetilde{A}_1^{\rm{ CLF}}=&-(m''_1-m'_1)^2+q^2-\hat N'_1-\hat N''_1+8A_1^{(2)}+2\Big[M'^{2}+M''^{2}+2(m'_1-m_2)(m_2-m''_1)-q^2\Big] A_1^{(1)}\nonumber\\
&-4(m_1'+m_1'')\left(\frac{1}{D_{ V,{\rm con}}'}+\frac{1}{D_{ V,{\rm con}}''}\right)A_1^{(2)}\,,\\
\widetilde{A}_2^{\rm{ CLF}}=&-\frac{q^2}{M'^{2}-{M''}^{2}} \bigg\{(m'_1-m''_1)^2-2(m_2-m'_1)^2+2{M'}^2-q^2-2Z_2-\hat N'_1+\hat N''_1\nonumber\\
&+\frac{4({M'}^2-{M''}^2)}{q^2}A_1^{(2)}+2\left[2(m_2-m'_1)(m_2-m''_1)-{M'}^2-{M''}^2+q^2+2Z_2 \right]A_2^{(1)}\nonumber\\
&-\frac{4}{D'_{ V,{\rm con}}}\left(m'_1-m''_1+2m_2\right)A_1^{(2)}-\frac{4}{D''_{ V,{\rm con}}}\left(m'_1-m''_1-2m_2\right)A_1^{(2)}\bigg\}+\widetilde{A}_1^{\rm{ CLF}}(x,{\bf k'_\bot},q^2)\,,
\\
\widetilde{A}_3^{\rm{CLF}}=&-4({M'}^{2}-{M''}^{2})\bigg\{A_1^{(1)}-A_2^{(1)}-A_2^{(2)}+A_4^{(2)}
\nonumber\\
&+\frac{1}{D_{ V,{\rm con}}''}\Big[ m'_1\left(-\bar x+2A_2^{(1)}-A_2^{(2)}-2A_3^{(2)}-A_4^{(2)}\right)+m''_1\left(-A_1^{(1)}+A_2^{(1)}+A_2^{(2)}-A_4^{(2)}\right)\nonumber\\
&+ 2m_2\left(-A_1^{(1)}+A_2^{(2)}+A_3^{(2)}\right) \Big]+\frac{2}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}\left(A_1^{(2)}-A_1^{(3)}-A_2^{(3)}\right)
\bigg\}\,,\\
\widetilde{A}_4^{\rm{CLF}}=&-4({M'}^{2}-{M''}^{2})\bigg\{A_1^{(1)}-A_2^{(1)}-A_2^{(2)}+A_4^{(2)}\nonumber\\
&+\frac{1}{D'_{ V,{\rm con}}}\Big[m'_1\left(A_2^{(1)}-A_1^{(1)}+A_2^{(2)}-A_4^{(2)}\right)+m''_1\left(-A_2^{(2)}+2A_3^{(2)}-A_4^{(2)}\right)+2m_2\left(A_2^{(2)}-A_3^{(2)}\right)\Big]\nonumber\\
&+\frac{2}{D'_{ V,{\rm con}}D''_{ V,{\rm con}}}\left(-A_1^{(3)}+A_2^{(3)}\right)
\bigg\}\,. \label{eq:A4CLF}
\end{align}
It should be noted that the contributions related to the $B$ functions are not included in the results given above. These contributions result in the self-consistence and covariance problems, and will be given and analyzed  separately in the next section.




