Based on the theoretical results given above, we then present our numerical results and discussions. The constituent quark masses and  Gaussian parameters $\beta$ are essential inputs for computing the form factors. Thus, firstly, we would like to clarify their values used in our calculation. The values of constituent quark masses suggested in the previous works based on the LFQMs and Gaussian type WF are collected in Table~\ref{tab:qm}, in which, the second column is the result obtained via variational analyses of meson mass spectra  for the Hamiltonian with a smeared-out hyperfine interaction~\cite{Choi:2015ywa}; the third and fourth columns are the values obtained by the variational principle for the linear and harmonic oscillator~(HO) confining potentials, respectively~\cite{Choi:2009ai} (some similar analyses are made also in Refs.~\cite{Choi:2007se,Choi:1997iq}); in the fifth column,  the light quark masses are fitted by using decay constants $f_\pi$, $f_K$ and the mean square radii $ \langle r^2_{\pi^+}  \rangle$, $ \langle r^2_{K^0}  \rangle$, and the heavy quark masses are determined by the mass of the spin-weighted average of the heavy quarkonium states and its variational principle~\cite{Hwang:2010hw}; the sixth and seventh columns are some commonly used values in the LFQMs~\cite{ Cheng:2003sm,Verma:2011yw}. The quark masses suggested in the other previous work are generally similar  to one of them.  From Table~\ref{tab:qm}, it can be easily found that the quark masses are model dependent, and their values obtained in the previous works are different from each other more or less.  In this work, we take a moderate choice for the default inputs~(central values) of quark masses, which are listed in the last column of Table~\ref{tab:qm}. In addition, we assign  a conservative error to each quark mass, which covers properly the other values listed in Table~\ref{tab:qm} and therefore can reflect roughly the uncertainties induced by the model dependence of quark mass. 
Then, in order to determine parameters $\beta$, we make fits to the  data of $f_V$ collected in Ref.~\cite{Chang:2018zjq} following the same way as Refs.~\cite{Chang:2018zjq,Chang:2019mmh} but with the default values of quark masses listed in  Table~\ref{tab:qm} as inputs. The fitting results for  $\beta$ are listed  in Table~\ref{tab:input}.  In addition, the type-II correspondence scheme is employed in the fits, while the fitting results do not affect following comparison between type-I and -II schemes.   






As has been mentioned in the last section, the contributions associated with $B$ functions are not included in the CLF results, Eqs.~(\ref{eq:V1CLF}-\ref{eq:A4CLF}). These contributions to the matrix elements can be written as
\begin{eqnarray}
[\mathcal B]_{\rm B}=N_c\int\frac{{\rm d} x{\rm d}^2{\bf k'_\bot}}{2(2\pi)^3}\frac{\chi_V'\chi_V''}{\bar x}{\cal \widetilde{\cal B}}_{\rm B}
\end{eqnarray}
where,
\begin{align}
{\cal \widetilde{B}}_{\rm B}^\mu(\Gamma= \gamma^\mu \gamma_5)=&-4i\epsilon_{\mu\nu\alpha\beta}\epsilon'^\nu P^\alpha q^\beta\left(\omega\cdot \epsilon''^{*}\right)\frac{B_1^{(2)}}{\omega\cdot P}\left(1+\frac{m_1'-m_1''-2m_2}{D_{V,{\rm con}}''}\right)\nonumber\\
&-4i\epsilon_{\mu\nu\alpha\beta}\epsilon''^{*\nu} P^\alpha q^\beta\left(\omega\cdot \epsilon'\right)\frac{B_1^{(2)}}{\omega\cdot P}\left(1-\frac{m_1'-m_1''+2m_2}{D_{V,{\rm con}}'}\right)\nonumber\\
&+4i\epsilon_{\mu\nu\alpha\beta}\epsilon'^\nu P^\alpha\omega^\beta\left(q\cdot \epsilon''^{*}\right)\frac{B_1^{(2)}}{\omega\cdot P}\left(1-\frac{m_1'+m_1''}{D_{V,{\rm con}}''}\right)\nonumber\\
&+4i\epsilon_{\mu\nu\alpha\beta}\epsilon'^\nu q^\alpha\omega^\beta\left(q\cdot \epsilon''^{*}\right)\frac{B_1^{(2)}}{\omega\cdot P}\left(1+\frac{m_1'-m_1''-2m_2}{D_{V,{\rm con}}''}\right)\nonumber\\
&+4i\epsilon_{\mu\nu\alpha\beta}\epsilon''^{*\nu} P^\alpha\omega^\beta\left(q\cdot \epsilon'\right)\frac{B_1^{(2)}}{\omega\cdot P}\left(1-\frac{m_1'+m_1''}{D_{V,{\rm con}}'}\right)\nonumber\\
&-4i\epsilon_{\mu\nu\alpha\beta}\epsilon''^{*\nu} q^\alpha\omega^\beta\left(q\cdot \epsilon'\right)\frac{B_1^{(2)}}{\omega\cdot P}\left(1-\frac{m_1'-m_1''+2m_2}{D_{V,{\rm con}}'}\right)\nonumber\\
&+8i\epsilon_{\mu\nu\alpha\beta}\omega^\nu P^\alpha q^\beta\left(q\cdot \epsilon'\right)\left(q\cdot \epsilon''^{*}\right)\frac{B_1^{(3)}-B_1^{(2)}}{\omega\cdot P}\cdot\frac 1{D_{V,{\rm con}}'D_{V,{\rm con}}''}\,, \label{eq:BBA}
\end{align}
and 
\begin{align}
{\cal \widetilde{B}}_B^\mu(\Gamma= \gamma^\mu)=&\frac{4}{\omega \cdot P}B_1^{(2)}\bigg\{(\epsilon'\cdot q)(\epsilon''^{*}\cdot \omega)P^\mu\Big[\frac{m'_1-m''_1}{D'_{V,{\rm con}}}+\frac{m'_1+m''_1-2m_2}{D''_{V,{\rm con}}}\nonumber\\
&+\frac{1}{D'_{V,{\rm con}}D''_{V,{\rm con}}}\big((m'_1-m''_1)^2-q^2-\hat N'_1+\hat N''_1\big)\Big]\nonumber\\
&+(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)P^\mu\Big[3-\frac{3m'_1+m''_1+2m_2}{D'_{V,{\rm con}}}-\frac{5m''_1+4m_2}{D''_{V,{\rm con}}}\nonumber\\
&-\frac{1}{D'_{V,{\rm con}}D''_{V,{\rm con}}}\big(2M'^2+2M''^2+(m'_1-m''_1)^2-4(m'_1+m_2)(m''_1+m_2)+3q^2+\hat N'_1+\hat N''_1\big)\Big]\nonumber\\
&+q^\mu\Big[(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)-(\epsilon'\cdot q)(\epsilon''^{*}\cdot \omega)\Big]\Big[2+\frac{-4m'_1+m''_1-2m_2}{D'_{V,{\rm con}}}-\frac{m''_1+2m_2}{D''_{V,{\rm con}}}\nonumber\\
&+\frac{1}{D'_{V,{\rm con}}D''_{V,{\rm con}}}\big(-2M'^2+2m_2^2+m'^2_1-m''^2_1+2m'_1(m''_1+2m_2)+q^2+\hat N'_1-\hat N''_1\big)\Big]\nonumber\\
&+(\epsilon'\cdot q)(\epsilon''^{*}\cdot q)\omega^\mu\Big[-3+\frac{4m'_1+2m''_1+2m_2}{D'_{V,{\rm con}}}+\frac{m'_1+4m''_1-2m_2}{D''_{V,{\rm con}}}\nonumber\\
&+\frac{2}{D'_{V,{\rm con}}D''_{V,{\rm con}}}(M'^2+M''^2-2(m'_1+m_2)(m''_1+m_2)-q^2)\Big]
\bigg\}\nonumber\\
&+\frac{16}{\omega \cdot P}B_1^{(3)}\bigg\{P^\mu\Big[(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)-(\epsilon'\cdot q)(\epsilon''^{*}\cdot \omega)\Big]\Big[-1+\frac{m'_1+m_2}{D'_{V,{\rm con}}}+\frac{m''_1+m_2}{D''_{V,{\rm con}}}\nonumber\\
&+\frac{1}{2D'_{V,{\rm con}}D''_{V,{\rm con}}}(M'^2+M''^2-2(m'_1+m_2)(m''_1+m_2)-q^2)\Big]\nonumber\\
&+(\epsilon'\cdot q)(\epsilon''^{*}\cdot q)\omega^\mu\Big[-1+\frac{m'_1+m_2}{D'_{V,{\rm con}}}+\frac{m''_1+m_2}{D''_{V,{\rm con}}}\nonumber\\
&+\frac{1}{2D'_{V,{\rm con}}D''_{V,{\rm con}}}\big(M'^2+M''^2-2(m'_1+m_2)(m''_1+m_2)-q^2\big)\Big]
\bigg\}\nonumber\\
&+\frac{16}{\omega \cdot P}B_2^{(3)}\bigg\{(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)P^\mu\Big[-1+\frac{m'_1+m_2}{D'_{V,{\rm con}}}+\frac{m''_1+m_2}{D''_{V,{\rm con}}}\nonumber\\
&+\frac{1}{2D'_{V,{\rm con}}D''_{V,{\rm con}}}\big(M'^2+M''^2-2(m'_1+m_2)(m''_1+m_2)-q^2\big)\Big]\nonumber\\
&+(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)q^\mu\Big[-1+\frac{m'_1+m_2}{D'_{V,{\rm con}}}+\frac{m''_1+m_2}{D''_{V,{\rm con}}}\nonumber\\
&+\frac{1}{2D'_{V,{\rm con}}D''_{V,{\rm con}}}\big(M'^2+M''^2-2(m'_1+m_2)(m''_1+m_2)-q^2\big)\Big]
\bigg\}\nonumber\\
&+\frac{16}{\omega \cdot P}\frac{B_3^{(3)}}{D'_{V,{\rm con}}D''_{V,{\rm con}}}\bigg\{(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)P^\mu+\frac{1}{2}\Big[(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)-(\epsilon'\cdot q)(\epsilon''^{*}\cdot \omega)\Big]q^\mu\nonumber\\
&-(\epsilon'\cdot q)(\epsilon''^{*}\cdot q)\omega^\mu
\bigg\}\nonumber\\
&+\frac{16}{\omega \cdot P}\frac{B_5^{(4)}}{D'_{V,{\rm con}}D''_{V,{\rm con}}}\bigg\{-\Big[(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)+(\epsilon'\cdot q)(\epsilon''^{*}\cdot \omega)\Big]P^\mu\nonumber\\
&-\frac{1}{2}\Big[(\epsilon'\cdot \omega)(\epsilon''^{*}\cdot q)-(\epsilon'\cdot q)(\epsilon''^{*}\cdot \omega)\Big]q^\mu
\bigg\}\,.\label{eq:BBV}
\end{align}
They may present nontrivial contributions to the form factors and  lead to the self-consistency and covariance problems of CLF QM. Then, the full results for form factors in the CLF QM can be expressed as
\begin{align}
[{\cal F}]^{\rm full}=[{\cal F}]^{\rm CLF}+[{\cal F}]^{\rm B}\,.
\end{align}


